SELECT EMPLID, EMPL_RCD, EFFDT, EFFSEQ, BIRTHDATE, FIRST_NAME, LAST_NAME, MIDDLE_NAME, ADDRESS1, CITY, STATE, POSTAL, GEO_CODE, SEX, MILITARY_STATUS, GVT_CRED_MIL_SVCE, GVT_MILITARY_COMP, GVT_MIL_RESRVE_CAT, GVT_VET_PREF_APPT, ETHNIC_GROUP, GVT_DISABILITY_CD
FROM (SELECT p.* FROM {{ ref('stg_ehrp2biis__ps_gvt_pers_data') }} p INNER JOIN (SELECT DISTINCT EMPLID, EMPL_RCD, EFFDT, EFFSEQ FROM {{ ref('stg_ehrp2biis__nwk_new_ehrp_actions_tbl') }}) n ON p.EMPLID = n.EMPLID AND p.EMPL_RCD = n.EMPL_RCD AND p.EFFDT = n.EFFDT AND p.EFFSEQ = n.EFFSEQ)
QUALIFY ROW_NUMBER() OVER (
    PARTITION BY EMPLID, EMPL_RCD, EFFDT, EFFSEQ
    ORDER BY LAST_NAME ASC NULLS LAST, FIRST_NAME ASC NULLS LAST, MIDDLE_NAME ASC NULLS LAST, ADDRESS1 ASC NULLS LAST, CITY ASC NULLS LAST, STATE ASC NULLS LAST, POSTAL ASC NULLS LAST, GEO_CODE ASC NULLS LAST, SEX ASC NULLS LAST, BIRTHDATE ASC NULLS LAST, MILITARY_STATUS ASC NULLS LAST, GVT_CRED_MIL_SVCE ASC NULLS LAST, GVT_MILITARY_COMP ASC NULLS LAST, GVT_MIL_RESRVE_CAT ASC NULLS LAST, GVT_VET_PREF_APPT ASC NULLS LAST, ETHNIC_GROUP ASC NULLS LAST, GVT_DISABILITY_CD ASC NULLS LAST
) = 1
